/* Concatenate the five design modules into two sibling files the page loads.
 *
 * WHY NOT INLINE THEM INTO index.html?
 * The modules are 325 KB of source, 43% of it documentation. Inlining would take the
 * page from 72 KB to ~400 KB and destroy the one measured competitive advantage this
 * product has — it transfers ~25 KB against a 2,164 KB median mobile page.
 *
 * Shipping them as two sibling files instead means:
 *   - index.html stays hand-editable and small; it changes often
 *   - the bundle changes rarely and caches independently, so a copy tweak does not
 *     re-download 180 KB of module code
 *   - still zero external hosts, zero CDN, zero build tooling beyond this script
 *
 * Comments are stripped from the SHIPPED bundle only. modules/*.js keep every word —
 * that is where the reasoning lives, and it is worth more than the bytes.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const MOD = path.join(__dirname, "modules");
const SITE = path.join(__dirname, "..");

/* load order matters: gameweek defines helpers the others may read */
const ORDER = ["gameweek", "chips", "tutorial", "share", "landing"];

/* LINE-BASED comment stripping only.
   A character-level stripper is the obvious approach and it is a trap: the first
   version desynced on a regex literal containing a quote and swallowed the URL out
   of an inline SVG. Only whole lines that are ENTIRELY comment are removed here, so
   no string, template or regex literal can ever be touched. It recovers most of the
   saving (the documentation is written in full-line blocks) at zero risk. */
function stripLines(src) {
  const NL = String.fromCharCode(10);
  const out = [];
  let inBlock = false;
  for (const raw of src.split(NL)) {
    const line = raw.replace(String.fromCharCode(13), "");
    const t = line.trim();
    if (inBlock) { if (t.endsWith("*/")) inBlock = false; continue; }
    if (t.startsWith("/*")) { if (!t.endsWith("*/")) inBlock = true; continue; }
    if (t.startsWith("//")) continue;
    out.push(line);
  }
  return out.join(NL).replace(new RegExp("(" + NL + "){3,}", "g"), NL + NL);
}
const stripJs = stripLines, stripCss = stripLines;

let js = "/* Goallak Fantasy modules — generated by scripts/build-bundle.mjs. Edit modules/*.js, not this. */\n";
let css = "/* Goallak Fantasy modules — generated by scripts/build-bundle.mjs. Edit modules/*.css, not this. */\n";
let rawJs = 0, rawCss = 0;

for (const name of ORDER) {
  const jf = path.join(MOD, name + ".js");
  const cf = path.join(MOD, name + ".css");
  if (fs.existsSync(jf)) {
    const s = fs.readFileSync(jf, "utf8");
    rawJs += s.length;
    js += "\n/* ==== " + name + " ==== */\n" + stripJs(s) + "\n";
  }
  if (fs.existsSync(cf)) {
    const s = fs.readFileSync(cf, "utf8");
    rawCss += s.length;
    css += "\n/* ==== " + name + " ==== */\n" + stripCss(s) + "\n";
  }
}

fs.writeFileSync(path.join(SITE, "modules.js"), js);
fs.writeFileSync(path.join(SITE, "modules.css"), css);

const pct = (a, b) => Math.round((1 - b / a) * 100) + "%";
console.log("modules.js   " + rawJs + " -> " + js.length + "  (" + pct(rawJs, js.length) + " smaller)");
console.log("modules.css  " + rawCss + " -> " + css.length + "  (" + pct(rawCss, css.length) + " smaller)");
console.log("shipped total: " + (js.length + css.length) + " bytes across 2 cacheable files");
